1	package com.loja.checkout.servico;
2	
3	import com.loja.checkout.dominio.ContextoCupom;
4	import com.loja.checkout.dominio.Cupom;
5	import com.loja.checkout.dominio.FormaPagamento;
6	import com.loja.checkout.dominio.Item;
7	import com.loja.checkout.dominio.ModalidadeEntrega;
8	import com.loja.checkout.dominio.NivelClube;
9	import com.loja.checkout.dominio.Regiao;
10	import com.loja.checkout.dominio.ResultadoPagamento;
11	import com.loja.checkout.erro.PedidoException;
12	import com.loja.checkout.util.Dinheiro;
13	import com.loja.checkout.web.dto.ItemRequest;
14	import com.loja.checkout.web.dto.ResumoRequest;
15	import com.loja.checkout.web.dto.ResumoResponse;
16	import java.math.BigDecimal;
17	import java.util.List;
18	import org.springframework.stereotype.Service;
19	
20	/**
21	 * Único lugar que conhece a ordem de validação e a ordem de cálculo do
22	 * resumo. Cada decisão específica de um caso (modalidade, cupom, nível do
23	 * clube, forma de pagamento) é delegada ao enum correspondente.
24	 */
25	@Service
26	public class CalculadoraResumo {
27	
28	    public ResumoResponse calcular(ResumoRequest pedido) {
29	        List<Item> itens = validarItens(pedido.itens());
30	        BigDecimal subtotalProdutos = Dinheiro.arredondar(somarSubtotal(itens));
31	        BigDecimal pesoTotal = somarPeso(itens);
32	
33	        NivelClube nivelClube = parseNivelClube(pedido.nivelClube());
34	        Regiao regiao = parseRegiao(pedido.regiao());
35	        BigDecimal seguro = regiao.calcularSeguro(subtotalProdutos);
36	
37	        ModalidadeEntrega modalidade = parseModalidade(pedido.modalidadeEntrega());
38	        modalidade.validarDisponibilidade(pesoTotal);
39	        BigDecimal frete = nivelClube.isentaFrete() ? BigDecimal.ZERO : modalidade.calcularFrete(pesoTotal);
40	
41	        BigDecimal descontoCupom = calcularDescontoCupom(pedido.cupom(), subtotalProdutos, itens, frete);
42	
43	        BigDecimal totalPedido = Dinheiro.arredondar(
44	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
45	
46	        FormaPagamento formaPagamento = parseFormaPagamento(pedido.formaPagamento());
47	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
48	        formaPagamento.validarParcelas(parcelas);
49	        formaPagamento.validarDisponibilidade(totalPedido);
50	
51	        ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
52	
53	        BigDecimal credito = nivelClube.calcularCredito(subtotalProdutos);
54	        boolean brinde = nivelClube.ganhaBrinde(subtotalProdutos);
55	
56	        return new ResumoResponse(
57	                subtotalProdutos,
58	                descontoCupom,
59	                frete,
60	                modalidade.prazoDias(),
61	                seguro,
62	                resultadoPagamento.ajuste(),
63	                resultadoPagamento.totalFinal(),
64	                parcelas,
65	                resultadoPagamento.valorParcela(),
66	                credito,
67	                brinde);
68	    }
69	
70	    private List<Item> validarItens(List<ItemRequest> itensRequest) {
71	        if (itensRequest == null || itensRequest.isEmpty()) {
72	            throw new PedidoException("PEDIDO_INVALIDO");
73	        }
74	        List<Item> itens = itensRequest.stream()
75	                .map(itemRequest -> new Item(
76	                        itemRequest.nome(),
77	                        itemRequest.precoUnitario(),
78	                        itemRequest.quantidade() == null ? 0 : itemRequest.quantidade(),
79	                        itemRequest.pesoKg()))
80	                .toList();
81	        if (itens.stream().anyMatch(item -> !item.valido())) {
82	            throw new PedidoException("PEDIDO_INVALIDO");
83	        }
84	        return itens;
85	    }
86	
87	    private BigDecimal somarSubtotal(List<Item> itens) {
88	        return itens.stream().map(Item::subtotal).reduce(BigDecimal.ZERO, BigDecimal::add);
89	    }
90	
91	    private BigDecimal somarPeso(List<Item> itens) {
92	        return itens.stream().map(Item::pesoTotal).reduce(BigDecimal.ZERO, BigDecimal::add);
93	    }
94	
95	    private NivelClube parseNivelClube(String nivelClube) {
96	        if (nivelClube == null) {
97	            throw new PedidoException("NIVEL_CLUBE_INVALIDO");
98	        }
99	        try {
100	            return NivelClube.valueOf(nivelClube);
101	        } catch (IllegalArgumentException excecao) {
102	            throw new PedidoException("NIVEL_CLUBE_INVALIDO");
103	        }
104	    }
105	
106	    private Regiao parseRegiao(String regiao) {
107	        if (regiao == null) {
108	            throw new PedidoException("REGIAO_INVALIDA");
109	        }
110	        try {
111	            return Regiao.valueOf(regiao);
112	        } catch (IllegalArgumentException excecao) {
113	            throw new PedidoException("REGIAO_INVALIDA");
114	        }
115	    }
116	
117	    private ModalidadeEntrega parseModalidade(String modalidadeEntrega) {
118	        if (modalidadeEntrega == null) {
119	            throw new PedidoException("MODALIDADE_INVALIDA");
120	        }
121	        try {
122	            return ModalidadeEntrega.valueOf(modalidadeEntrega);
123	        } catch (IllegalArgumentException excecao) {
124	            throw new PedidoException("MODALIDADE_INVALIDA");
125	        }
126	    }
127	
128	    private BigDecimal calcularDescontoCupom(String cupomCodigo, BigDecimal subtotalProdutos, List<Item> itens,
129	            BigDecimal frete) {
130	        if (cupomCodigo == null) {
131	            return BigDecimal.ZERO;
132	        }
133	        Cupom cupom;
134	        try {
135	            cupom = Cupom.valueOf(cupomCodigo);
136	        } catch (IllegalArgumentException excecao) {
137	            throw new PedidoException("CUPOM_INVALIDO");
138	        }
139	        ContextoCupom contexto = new ContextoCupom(subtotalProdutos, itens, frete);
140	        cupom.validarAplicavel(contexto);
141	        return cupom.calcularDesconto(contexto);
142	    }
143	
144	    private FormaPagamento parseFormaPagamento(String formaPagamento) {
145	        if (formaPagamento == null) {
146	            throw new PedidoException("FORMA_PAGAMENTO_INVALIDA");
147	        }
148	        try {
149	            return FormaPagamento.valueOf(formaPagamento);
150	        } catch (IllegalArgumentException excecao) {
151	            throw new PedidoException("FORMA_PAGAMENTO_INVALIDA");
152	        }
153	    }
154	}
