1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.erro.PedidoException;
4	import com.loja.checkout.util.Dinheiro;
5	import java.math.BigDecimal;
6	
7	/**
8	 * Cada forma de pagamento carrega sua própria regra de parcelamento, sua
9	 * própria condição de disponibilidade e sua própria fórmula de ajuste sobre
10	 * o total do pedido.
11	 */
12	public enum FormaPagamento {
13	
14	    PIX {
15	        @Override
16	        public boolean parcelasValidas(int parcelas) {
17	            return parcelas == 1;
18	        }
19	
20	        @Override
21	        public boolean disponivelPara(BigDecimal totalPedido) {
22	            return true;
23	        }
24	
25	        @Override
26	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
27	            BigDecimal desconto = Dinheiro.arredondar(totalPedido.multiply(new BigDecimal("0.05")));
28	            BigDecimal totalFinal = totalPedido.subtract(desconto);
29	            return new ResultadoPagamento(totalFinal, totalFinal, desconto.negate());
30	        }
31	    },
32	
33	    BOLETO {
34	        private final BigDecimal tarifa = new BigDecimal("3.49");
35	
36	        @Override
37	        public boolean parcelasValidas(int parcelas) {
38	            return parcelas == 1;
39	        }
40	
41	        @Override
42	        public boolean disponivelPara(BigDecimal totalPedido) {
43	            return totalPedido.compareTo(new BigDecimal("1000.00")) <= 0;
44	        }
45	
46	        @Override
47	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
48	            BigDecimal totalFinal = totalPedido.add(tarifa);
49	            return new ResultadoPagamento(totalFinal, totalFinal, tarifa);
50	        }
51	    },
52	
53	    CARTAO {
54	        private final BigDecimal taxaMensal = new BigDecimal("0.0199");
55	
56	        @Override
57	        public boolean parcelasValidas(int parcelas) {
58	            return parcelas >= 1 && parcelas <= 12;
59	        }
60	
61	        @Override
62	        public boolean disponivelPara(BigDecimal totalPedido) {
63	            return true;
64	        }
65	
66	        @Override
67	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
68	            if (parcelas <= 3) {
69	                BigDecimal valorParcela = Dinheiro.arredondar(
70	                        totalPedido.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
71	                return new ResultadoPagamento(totalPedido, valorParcela, BigDecimal.ZERO);
72	            }
73	            double taxa = taxaMensal.doubleValue();
74	            double fator = taxa / (1 - Math.pow(1 + taxa, -parcelas));
75	            BigDecimal valorParcela = Dinheiro.arredondar(totalPedido.multiply(BigDecimal.valueOf(fator)));
76	            BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
77	            return new ResultadoPagamento(totalFinal, valorParcela, totalFinal.subtract(totalPedido));
78	        }
79	    };
80	
81	    public abstract boolean parcelasValidas(int parcelas);
82	
83	    public abstract boolean disponivelPara(BigDecimal totalPedido);
84	
85	    public abstract ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas);
86	
87	    public final void validarParcelas(int parcelas) {
88	        if (!parcelasValidas(parcelas)) {
89	            throw new PedidoException("PARCELAMENTO_INVALIDO");
90	        }
91	    }
92	
93	    public final void validarDisponibilidade(BigDecimal totalPedido) {
94	        if (!disponivelPara(totalPedido)) {
95	            throw new PedidoException("FORMA_PAGAMENTO_INDISPONIVEL");
96	        }
97	    }
98	}
